/* From Uiverse.io by biswacpcode - Tags: button */
.__UIV_SCOPE__ button {
  color: white;
  text-decoration: none;
  font-size: 25px;
  border: none;
  background: none;
  font-weight: 600;
  font-family: 'Poppins', sans-serif;
}

.__UIV_SCOPE__ button::before {
  margin-left: auto;
}

.__UIV_SCOPE__ button::after, .__UIV_SCOPE__ button::before {
  content: '';
  width: 0%;
  height: 2px;
  background: #f44336;
  display: block;
  transition: 0.5s;
}

.__UIV_SCOPE__ button:hover::after, .__UIV_SCOPE__ button:hover::before {
  width: 100%;
}
